#!/usr/bin/env python3
import r2pipe

def analyze_binary(binary_path):
    r2 = r2pipe.open(binary_path)
    r2.cmd('aa')  # Analyze all

    # Get main function info
    print("=== Main Function Analysis ===")
    print(r2.cmd('pdf @main'))

    # Get strings
    print("\n=== Important Strings ===")
    strings = r2.cmdj('izj')
    if strings:
        interesting_strings = ['Wrong', 'flag', 'Usage']
        for s in strings:
            for keyword in interesting_strings:
                if keyword.lower() in s['string'].lower():
                    print(f"String at {hex(s['vaddr'])}: {s['string']}")

    # Get function list
    print("\n=== Functions ===")
    functions = r2.cmdj('aflj')
    if functions:
        for f in functions:
            print(f"Function {f['name']} at {hex(f['offset'])}")

    r2.quit()

analyze_binary('/home/ctfplayer/ctf_files/callsite')

